validator:
function validate(input) {
  const [{ Calls = [] }] = input;
  for (const [from, to, duration] of Calls) {
    if (from === null || to === null || duration === null) return 'Every call needs from_id, to_id and duration.';
    if (from === to) return `Person ${from} cannot call themselves.`;
    if (duration <= 0) return 'Every duration must be positive.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const people = small ? 4 : 60, count = small ? Math.floor(rand() * 9) : 2000;
  const durations = [5, 10, 20, 59, 100, 200];
  const Calls = [];
  for (let i = 0; i < count; i++) {
    // Repeat an earlier call now and then so identical rows appear.
    if (Calls.length && rand() < 0.15) { Calls.push([...Calls[Math.floor(rand() * Calls.length)]]); continue; }
    const from = 1 + Math.floor(rand() * people);
    let to = 1 + Math.floor(rand() * (people - 1));
    if (to >= from) to++;
    const duration = small ? durations[Math.floor(rand() * durations.length)] : 1 + Math.floor(rand() * 1000);
    Calls.push([from, to, duration]);
  }
  return [{ Calls }];
}
